import Vue from 'vue';
import { inversifyContainer } from '../../../inversify/container';
import { environment } from '../../../services/environment';
import { gameConfig } from '../../../models/config-model';
import { queryStringParams } from '../../../services/query-string';
import { AssetManager } from '@game-studio/asset-manager';

function getRegionFolder(): string | 'base' {
    const region = queryStringParams.locale;
    switch (region) {
        case 'it-it':
            return 'it';
        case 'es-es':
            return 'es';
        case 'se-se':
            return 'se';
        case 'dk-dk':
            return 'dk';
        case 'en-gb':
        default:
            return 'base';
    }
}

export const BaseComponent = Vue.extend({
    props: {
        base: {
            type: Object,
            default: () => ({
                maxWidth: '100%',
                align: 'center',
            }),
        },
        alignText: {
            type: String,
            default: 'center',
        },
    },
    methods: {
        assetPath: function (file: string) {
            if (file.startsWith('ASS-MAN:')) {
                file = file.replace('ASS-MAN:', '');
                const fileKey = file.replace(/\.[^.]*$/, '');
                const texture = AssetManager.getTexture(fileKey);

                if (texture && texture.source && texture.source.resource) {
                    const resource: any = texture.source.resource;

                    if (resource instanceof HTMLImageElement && resource.src) {
                        return resource.src;
                    }
                }
            } else {
                const skinFolder = gameConfig.assetFolder;
                const regionFolder = getRegionFolder();
                const simplifiedRegion = regionFolder.split('-')[0];

                if (environment === 'debug' && process.env.LOCALASSETPORT !== void (0)) {
                    return `http://127.0.0.1:${process.env.LOCALASSETPORT}/static/assets/${skinFolder}/${simplifiedRegion}/htp/${file}`;
                }

                return './static/assets/' + skinFolder + '/' + simplifiedRegion + '/htp/' + file;
            }
            return '';
        },
        localisedString: function (stringName: string) {
            if (inversifyContainer.strings.vueHtp && (stringName in inversifyContainer.strings.vueHtp)) {
                return inversifyContainer.strings.vueHtp[stringName];
            }
            return stringName;
        }
    },
    computed: {
        containerStyle() {
            const width =
                typeof this.base.maxWidth === 'number'
                    ? this.base.maxWidth + 'px'
                    : this.base.maxWidth;

            const align =
                this.base.align === 'left'
                    ? 'flex-start'
                    : this.base.align === 'right'
                        ? 'flex-end'
                        : 'center';
            return {
                maxWidth: width,
                'justify-self': align,
            };
        },
        textStyle() {
            return {
                'text-align': this.alignText,
            };
        },
    },
}) as typeof Vue;
